INSERT INTO `news` VALUES (1,'A A-1 Pictures confirmou oficialmente que a produção da segunda temporada já está em andamento, prometendo cobrir o arco da Ilha Jeju...','https://scc10.com.br/wp-content/uploads/2026/02/solo_leveling_.webp','O fenômeno coreano retorna com novos episódios ainda este ano.','2026-03-21 20:57:12.000000','Segunda Temporada de Solo Leveling Confirmada!'),(2,'Fontes ligadas à Rockstar Games sugerem que a densidade urbana e as áreas rurais de Vice City foram expandidas drasticamente para a nova geração...','https://sm.ign.com/t/ign_br/gallery/g/gta-6-vice/gta-6-vice-city-screenshots_h3ga.1200.jpg','Novos rumores indicam que o mapa de Leonida será o dobro de Los Santos.','2026-03-21 18:57:12.000000','GTA VI: Vazamentos sugerem mapa imenso'),(3,'Rumores na indústria indicam que o mestre Tite Kubo está finalizando um projeto especial que será anunciado na próxima Jump Festa...','https://cdn.ome.lt/Sm-isKSs58MhQpSPZTR75R0vhrg=/987x0/smart/filters:format(webp)/uploads/conteudo/fotos/bleach_novo_manga.jpg','Tite Kubo pode estar trabalhando em um novo One-shot para a Shonen Jump.','2026-03-20 20:57:12.000000','Novo mangá do autor de Bleach?'),(4,'Documentos internos revelam que a Sony já está em conversas com a AMD para o desenvolvimento do chip customizado que alimentará o sucessor do PS5...','https://pt.egw.news/_next/image?url=https%3A%2F%2Fegw.news%2Fuploads%2Fnews%2F1%2F17%2F1760471363590_1760471363590.webp&w=1920&q=75','Arquitetura de próxima geração focará em Ray Tracing em tempo real sem perda de performance.','2026-03-18 20:57:12.000000','PlayStation 6: Sony inicia discussões sobre hardware'),(5,'Novos relatórios de desenvolvedores que já possuem o devkit do sucessor do Switch indicam que a retrocompatibilidade física e digital é total, com upscale automático para 4K no dock...','https://www.fayerwayer.com/resizer/v2/T2CJCUKSLFFYJIBGAIWS4M62OM.jpeg?smart=true&auth=e566bb15e78311a2c2bc4d98f3c46e0aaa86cb0139fb6b2d73aee1b21dda1164&width=1600&height=900','Testes vazados confirmam que jogos do Switch 1 rodam com melhorias de performance.','2026-03-21 20:20:48.000000','Nintendo Switch 2: Primeiras impressões da Retrocompatibilidade'),(6,'Em um documentário recente, Neil Druckmann revelou que encontrou o \"conceito ideal\" para fechar a história. Fontes ligadas ao estúdio confirmam que a produção em larga escala começou este mês...','https://wallpapers.com/images/hd/training-in-forest-the-last-of-us-nr9h6klvzkhamyi6.webp','O capítulo final da saga de Ellie e Abby começa a ganhar forma nos estúdios da Naughty Dog.','2026-03-21 09:20:48.000000','The Last of Us Part III: Druckmann confirma início da captura de movimentos'),(7,'Diferente da versão da Netflix, este novo remake promete fidelidade absoluta ao traço de Shingo Araki e uma trilha sonora rearranjada da original de Seiji Yokoyama...','https://uploads.folhavitoria.com.br/2024/11/fFbQ2HHv-c4ee6940-e2de-11ee-9979-5d24ad15ce58-minified.webp','Toei Animation revela novo projeto em computação gráfica de altíssimo orçamento.','2026-03-19 21:20:48.000000','Cavaleiros do Zodíaco: Remake da Saga do Santuário anunciado'),(8,'A Bandai Namco celebrou o marco histórico, confirmando que Elden Ring agora faz parte do panteão dos jogos mais vendidos de todos os tempos, superando expectativas iniciais...','https://sm.ign.com/t/ign_br/gallery/e/elden-ring/elden-ring-shadow-of-the-erdtree-release-date-trailer-screen_h6hq.1200.jpg','A expansão da FromSoftware quebra recordes de vendas para um DLC.','2026-03-18 21:20:48.000000','Elden Ring: Shadow of the Erdtree atinge 20 milhões de cópias');
